DEMON_CATALOGS.lores = DEMON_CATALOGS.lores.map(entry => ({
  ...entry,
  ...(DEMON_LORE_DETAILS[entry.key] ?? {})
}));

export function getDemonCatalogEntry(catalog, key) {
  const list = DEMON_CATALOGS[catalog] ?? [];
  return list.find(entry => entry.key === key) ?? null;
}
